import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"Open API","description":"","frontmatter":{},"headers":[],"relativePath":"console/openapi.md","filePath":"console/openapi.md","lastUpdated":1782304957000}'),o={name:"console/openapi.md"};function r(n,t,p,d,s,c){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="open-api" tabindex="-1">Open API <a class="header-anchor" href="#open-api" aria-label="Permalink to &quot;Open API&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：用 Open API 把 V3 的能力接入你自己的系统。</p></blockquote><h2 id="什么是-open-api" tabindex="-1">什么是 Open API <a class="header-anchor" href="#什么是-open-api" aria-label="Permalink to &quot;什么是 Open API&quot;">​</a></h2><p>除了 Web 控制台，V3 还提供 <strong>HTTP API</strong>，凭 <strong>API Key</strong> 调用，方便你做二次集成：</p><ul><li>在自己的网站 / App 里查询机器人状态。</li><li>用脚本批量管理。</li><li>和其他系统对接。</li></ul><h2 id="创建-api-key" tabindex="-1">创建 API Key <a class="header-anchor" href="#创建-api-key" aria-label="Permalink to &quot;创建 API Key&quot;">​</a></h2><ol><li>进入控制台的 Open API 页面。</li><li>点「创建 API Key」。</li><li>给 Key 起个名字（标记用途）。</li><li>保存生成的 Key。</li></ol><div class="warning custom-block"><p class="custom-block-title">妥善保管</p><p>API Key 等同于你的账户凭证，泄露后别人能用它操作你的账户。创建后只显示一次，记得保存；不用了及时删除。</p></div><h2 id="调用方式" tabindex="-1">调用方式 <a class="header-anchor" href="#调用方式" aria-label="Permalink to &quot;调用方式&quot;">​</a></h2><p>所有 API 请求：</p><ul><li>带上 <code>Authorization: Bearer &lt;你的API Key&gt;</code> 请求头。</li><li>按接口文档传参。</li></ul><h2 id="api-文档" tabindex="-1">API 文档 <a class="header-anchor" href="#api-文档" aria-label="Permalink to &quot;API 文档&quot;">​</a></h2><p>Open API 页面提供<strong>交互式接口文档</strong>，可：</p><ul><li>查看所有可用接口、参数、返回格式。</li><li>在页面上直接试调（填参数、发请求、看结果）。</li><li>复制调用示例。</li></ul><p>常见接口类型：</p><table tabindex="0"><thead><tr><th>类别</th><th>示例</th></tr></thead><tbody><tr><td>机器人管理</td><td>列出 / 创建 / 启停机器人</td></tr><tr><td>插件管理</td><td>列出已装插件、安装 / 卸载</td></tr><tr><td>消息发送</td><td>主动给指定目标发消息</td></tr><tr><td>订阅 / 账户</td><td>查询余额、订阅状态</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">先看交互式文档</p><p>具体接口路径、参数以控制台里的交互式文档为准（它会随版本更新）。本页只做概念介绍。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>管理你的机器人 → <a href="./bots">机器人管理</a></li><li>了解整体能力 → <a href="./../guide/features">核心特性</a></li></ul>',19)])])}const P=a(o,[["render",r]]);export{u as __pageData,P as default};
